void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 size = iResolution.xy + (0.5+(sin(iTime*0.1)*0.5));
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/size * 1.0;
    float speed = 64.0;
    vec2 offset = vec2(iTime*speed, iTime*speed)/size  + (sin(iTime*0.125) * 0.125);
    vec2 offset2 = vec2(-iTime*speed, -iTime*speed)/size * 0.5  + (cos(iTime*0.33) * 0.15);;
    vec2 offset3 = vec2(-iTime*speed, iTime*speed)/size * 0.4 + (sin(iTime*0.25) * 0.2);
    vec2 offset4 = vec2(-iTime*speed, iTime*speed)/size * 0.125 + (cos(iTime*0.2) * 0.5);
    float mnoise = texture(iChannel1, uv+offset).r;
    float mnoise2 = texture(iChannel0, uv+offset2).r;
    float mnoise3 = texture(iChannel0, uv+offset3).r;
    float mnoise4 = texture(iChannel1, uv+offset4).r;
    float mnoise5 = max(mnoise2, mnoise3);
    mnoise *= mnoise2 * mnoise3;
    uv = vec2(sin(mnoise*iTime), cos(mnoise*iTime));

    // Time varying pixel color
    vec3 col = mix(vec3(1.0, 0, 0), vec3(0, 0, 1.0), mnoise5);
    vec3 col2 = mix(vec3(1.0, 0.5, 0.25), vec3(0.5, 0.25, 0), mnoise);
    vec3 col3 = mix(vec3(0.5, 0.5, 1.0), vec3(0.25, 0.75, 0), mnoise4);
    vec3 mul = col/col2/col3 / 3.0;

    // Output to screen
    vec3 outVal = vec3(min(mul, col).rgb) * mnoise4 * mnoise2;
    vec3 outVal2 = vec3(min(mul, col).rgb) * mnoise3 * mnoise;
    vec3 outVal3 = vec3(min(mul, col).rgb + vec3(outVal + (outVal * outVal2)));
    fragColor = vec4(outVal3, 1.0) - vec4(min(outVal, min((outVal/outVal2), outVal3)), 1.0);
}
